#!/usr/bin/env python3
"""enumerate_local.py — 本机权限面枚举，输出 JSON。
用法: python3 enumerate_local.py > report.json
仅依赖标准库，Linux/macOS 为主，Windows 降级处理。
"""
import json, os, pwd, grp, stat, shlex, subprocess, platform
from datetime import datetime, timezone

def sh(cmd: str, timeout=15) -> str:
    try:
        return subprocess.run(shlex.split(cmd), capture_output=True,
                              text=True, timeout=timeout).stdout.strip()
    except Exception as e:
        return f"__ERROR__: {e}"

# --- 1. 服务: systemd / launchctl / Windows service ---
def list_services():
    sysname = platform.system()
    if sysname == "Linux":
        out = sh("systemctl list-units --type=service --state=running --no-pager --no-legend")
        services = []
        for line in out.splitlines():
            parts = line.split()
            if parts:
                services.append({"unit": parts[0], "state": "running"})
        return services
    if sysname == "Darwin":
        out = sh("launchctl list")
        return [{"pid": p, "label": lab}
                for p, lab, *_ in (l.split("\t") for l in out.splitlines() if l) if lab]
    if sysname == "Windows":
        out = sh("sc query state= all")
        entries, cur = [], {}
        for line in out.splitlines():
            line = line.strip()
            if line.startswith("SERVICE_NAME:"):
                if cur: entries.append(cur)
                cur = {"name": line.split(":", 1)[1].strip()}
            elif line.startswith("STATE") and cur is not None:
                cur["state"] = line.split(":", 1)[1].strip()
        if cur: entries.append(cur)
        return entries
    return []

# --- 2. 计划任务: crontab / systemd timers / schtasks ---
def list_scheduled_tasks():
    tasks = []
    # user crontab
    for u in (sh("cut -d: -f1 /etc/passwd").splitlines() or []):
        c = sh(f"crontab -l -u {shlex.quote(u)} 2>/dev/null")
        if c and not c.startswith("__ERROR__"):
            for line in c.splitlines():
                if line.strip() and not line.startswith("#"):
                    tasks.append({"user": u, "type": "user_cron", "entry": line})
    # system cron files
    for path in ("/etc/crontab",):
        if os.path.exists(path):
            with open(path) as f:
                for line in f:
                    if line.strip() and not line.startswith("#"):
                        tasks.append({"user": "root", "type": "system_cron", "entry": line.strip()})
    # systemd timers
    out = sh("systemctl list-timers --all --no-pager --no-legend")
    for line in out.splitlines():
        parts = line.split()
        if parts:
            tasks.append({"type": "systemd_timer", "next": parts[0], "unit": parts[-1]})
    # windows
    if platform.system() == "Windows":
        out = sh("schtasks /query /fo CSV /v")
        for line in out.splitlines()[1:]:
            tasks.append({"type": "schtasks", "raw": line})
    return tasks

# --- 3. 可写目录 (PATH / 常见位置 / 服务目录) ---
def list_writable_dirs():
    candidates = set(os.environ.get("PATH", "").split(os.pathsep))
    candidates.update(["/tmp", "/var/tmp", "/dev/shm", "/etc", "/usr/local/bin",
                       "/opt", os.path.expanduser("~")])
    # 加上 passwd 里 home 目录
    for line in (open("/etc/passwd").read().splitlines() if os.path.exists("/etc/passwd") else []):
        fields = line.split(":")
        if len(fields) > 5:
            candidates.add(fields[5])
    result = []
    for d in sorted(c for c in candidates if c and os.path.isdir(c)):
        try:
            if os.access(d, os.W_OK):
                st = os.stat(d)
                result.append({
                    "path": d,
                    "mode": oct(stat.S_IMODE(st.st_mode)),
                    "owner": pwd.getpwuid(st.st_uid).pw_name if hasattr(pwd, "getpwuid") else st.st_uid,
                    "sticky": bool(st.st_mode & stat.S_ISVTX),
                })

