#!/usr/bin/env python3
# scan_directory.py — stage 1: walk a tree, emit a deterministic manifest.
# contract: scan_directory(root) -> [(path, size, mtime)]
# usage:
#   python3 scan_directory.py /srv/data --manifest manifest.json
#   python3 scan_directory.py . --exclude '*.log' --exclude '.git' --jobs 8

from __future__ import annotations

import argparse
import fnmatch
import json
import os
import sys
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass, asdict
from pathlib import Path
from typing import Iterable, List, Sequence, Tuple

DEFAULT_EXCLUDES = (".git", ".svn", "node_modules", "__pycache__", "*.sock")


@dataclass(frozen=True)
class Entry:
    path: str      # POSIX-style path relative to root
    size: int      # bytes; -1 for symlinks/dangling refs
    mtime: float   # st_mtime as float seconds


def _stat_one(root: Path, rel: str) -> Entry | None:
    full = root / rel
    try:
        st = os.lstat(full)
    except OSError:
        return None
    if os.path.islink(st and full):
        return Entry(rel, -1, float(st.st_mtime))
    if not os.path.isfile(full):
        return None
    return Entry(rel, int(st.st_size), float(st.st_mtime))


def _walk(root: Path, excludes: Sequence[str]) -> Iterable[str]:
    stack = [""]
    while stack:
        rel_dir = stack.pop()
        base = root / rel_dir
        try:
            names = sorted(os.listdir(base))
        except OSError:
            continue
        for name in names:
            rel = f"{rel_dir}/{name}" if rel_dir else name
            if any(fnmatch.fnmatch(name, p) or fnmatch.fnmatch(rel, p)
                   for p in excludes):
                continue
            full = root / rel
            if os.path.isdir(full) and not os.path.islink(full):
                stack.append(rel)
            else:
                yield rel


def scan_directory(root: str | Path,
                   excludes: Sequence[str] = DEFAULT_EXCLUDES,
                   jobs: int = 8) -> List[Entry]:
    root = Path(root).expanduser().resolve()
    if not root.is_dir():
        raise NotADirectoryError(root)
    rels = list(_walk(root, excludes))
    if jobs <= 1 or len(rels) < 64:
        out = [_stat_one(root, r) for r in rels]
    else:
        with ThreadPoolExecutor(max_workers=jobs) as pool:
            out = list(pool.map(lambda r: _stat_one(root, r), rels))
    entries = [e for e in out if e is not None]
    entries.sort(key=lambda e: e.path)          # deterministic order
    return entries


def build_manifest(entries: Sequence[Entry], root: Path) -> dict:
    total = sum(e.size for e in entries if e.size > 0)
    return {
        "version": 1,
        "root": str(root),
        "file_count": len(entries),
        "total_bytes": total,
        "files": [asdict(e) for e in entries],
    }


def write_manifest(manifest: dict, dest: Path) -> Path:
    dest.parent.mkdir(parents=True, exist_ok=True)
    tmp = dest.with_suffix(dest.suffix + ".tmp")
    tmp.write_text(json.dumps(manifest, indent=2, sort_keys=True),
                   encoding="utf-8")
    tmp.replace(dest)                            # atomic on POSIX
    return dest


def load_manifest(path: Path) -> dict:
    data = json.loads(Path(path).read_text(encoding="utf-8"))
    if data.get("version") != 1:
        raise ValueError(f"unsupported manifest version: {data.get('version')}")
    return data


