    'php'    => PHP_BINARY,
    'phpunit'=> '/usr/local/bin/phpunit',
    'node'   => '/usr/bin/node',
    'pytest' => '/usr/local/bin/pytest',
    'ls'     => '/bin/ls',
];

$name = (string)($_POST['cmd'] ?? '');
if (!isset(ALLOWED[$name])) {
    http_response_code(400);
    exit(json_encode(['error' => 'unknown command']));
}

// 3) 参数以数组传递，绝不拼接字符串、绝不经过 shell
$args = [ALLOWED[$name]];
$extra = json_decode((string)($_POST['args'] ?? '[]'), true);
if (is_array($extra)) {
    foreach ($extra as $a) {
        if (!is_scalar($a)) { http_response_code(400); exit(json_encode(['error' => 'bad args'])); }
        $args[] = (string)$a;
    }
}

// 4) 限额：超时 1–30s，输出 256 KiB
$timeout = min(max((int)($_POST['timeout'] ?? 10), 1), 30);
$maxOut  = 262144;

$desc = [0 => ['pipe', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']];
$proc = proc_open($args, $desc, $pipes, null, null, ['bypass_shell' => true]);
if (!is_resource($proc)) {
    http_response_code(500);
    exit(json_encode(['error' => 'spawn failed']));
}
fclose($pipes[0]);

stream_set_blocking($pipes[1], false);
stream_set_blocking($pipes[2], false);

$stdout = $stderr = '';
$open   = [1 => $pipes[1], 2 => $pipes[2]];
$deadline = microtime(true) + $timeout;
$t0 = microtime(true);

while ($open) {
    $left = $deadline - microtime(true);
    if ($left <= 0) { proc_terminate($proc, 9); break; }

    $read = array_values($open); $w = null; $e = null;
    $n = @stream_select($read, $w, $e, (int)$left, (int)(fmod($left, 1) * 1e6));
    if ($n === false || $n === 0) continue;

    foreach ($read as $stream) {
        $chunk = fread($stream, 8192);
        if ($chunk === false || ($chunk === '' && feof($stream))) {
