以下是一个用于 Linux 系统安全审计与配置检查的 Python 基础枚举脚本。该脚本使用标准库获取当前用户权限、运行服务、计划任务、可写目录以及 SUID 文件，并将结果整理为 JSON 格式输出。

```python
import json
import os
import subprocess


def get_user_info():
    return {
        "uid": os.getuid(),
        "gid": os.getgid(),
        "groups": os.getgroups(),
        "username": os.getlogin() if hasattr(os, "getlogin") else None,
    }


def get_services():
    try:
        res = subprocess.run(
            [
                "systemctl",
                "list-units",
                "--type=service",
                "--state=running",
                "--no-pager",
                "--no-legend",
            ],
            capture_output=True,
            text=True,
            timeout=5,
        )
        services = [
            line.split()[0] for line in res.stdout.strip().split("\n") if line
        ]
        return services
    except Exception as e:
        return {"error": str(e)}


def get_cron_jobs():
    jobs = {}
    # 当前用户的 crontab
    try:
        res = subprocess.run(
            ["crontab", "-l"], capture_output=True, text=True, timeout=5
        )
        jobs["user_crontab"] = (
            res.stdout.strip().split("\n") if res.returncode == 0 else []
        )
    except Exception as e:
        jobs["user_crontab"] = str(e)

    # 常见系统计划任务目录
    cron_dirs = ["/etc/cron.d", "/etc/cron.daily", "/etc/cron.hourly"]
    system_cron = {}
    for d in cron_dirs:
        if os.path.exists(d) and os.path.isdir(d):
            try:
                system_cron[d] = os.listdir(d)
            except PermissionError:
                system_cron[d] = "Permission Denied"
    jobs["system_cron"] = system_cron
    return jobs


def get_suid_files():
    suid_files = []
    # 限制在常见二进制目录检索，避免全盘扫描耗时过长
    search_paths = ["/bin", "/sbin", "/usr/bin", "/usr/sbin"]
    for path in search_paths:
        if not os.path.exists(path):
            continue
        for root, _, files in os.walk(path):
            for f in files:
                full_path = os.path.join(root, f)
                try:
                    stat_info = os.stat(full_path, follow_symlinks=False)
                    # 检查 SUID 权限位 (0o4000)
                    if stat_info.st_mode & 0o4000:
                        suid_files.append(full_path)
                except (PermissionError, FileNotFoundError):
                    continue
    return suid_files


def get_writable_directories():
    writable = []
    # 检查常见公共目录
    check_paths = ["/tmp", "/var/tmp", "/dev/shm", "/etc"]
    for path in check_paths:
        if os.path.exists(path) and os.access(path, os.W_OK):
            writable.append(path)
    return writable


def audit_system():
    report = {
        "user_privileges": get_user_info(),
        "running_services": get_services(),
        "cron_jobs": get_cron_jobs(),
        "suid_files": get_suid_files(),
        "writable_directories": get_writable_directories(),
    }
    return json.dumps(report, indent=4, ensure_ascii=False)


if __name__ == "__main__":
    print(audit_system())
