    'df'     => ['cmd' => ['df', '-h'],                 'argc' => 0],
    'uptime' => ['cmd' => ['uptime'],                   'argc' => 0],
    'tail'   => ['cmd' => ['tail', '-n', '{0}', '%s'],  'argc' => 2],
    'status' => ['cmd' => ['systemctl', 'status', '{0}', '--no-pager'], 'argc' => 1],
];

function runOp(string $op, array $args): array {
    if (!isset(OPS[$op])) {
        return ['ok' => false, 'exit' => 64, 'output' => "unknown op\n"];
    }
    $spec  = OPS[$op];
    $args  = array_slice($args, 0, $spec['argc']);
    if (count($args) !== $spec['argc']) {
        return ['ok' => false, 'exit' => 64, 'output' => "bad argument count\n"];
    }

    $argv = [];
    foreach ($spec['cmd'] as $tpl) {
        $tpl = vsprintf($tpl, $args);
        $argv[] = str_contains($tpl, '%s') ? escapeshellarg($tpl) : $tpl;
    }
    $cmdline = implode(' ', $argv);

    $desc = [1 => ['pipe', 'w'], 2 => ['pipe', 'w']];
    $proc = proc_open($cmdline, $desc, $pipes, null, null, ['bypass_shell' => false]);
    if (!is_resource($proc)) {
        return ['ok' => false, 'exit' => 70, 'output' => "proc_open failed\n"];
    }
    stream_set_blocking($pipes[1], false);
    stream_set_blocking($pipes[2], false);

    $out = ''; $deadline = time() + 10;
    while (true) {
        $out .= stream_get_contents($pipes[1]) . stream_get_contents($pipes[2]);
        $st = proc_get_status($proc);
        if (!$st['running'] || time() > $deadline) { proc_terminate($proc); break; }
        usleep(20000);
    }
    $out .= stream_get_contents($pipes[1]) . stream_get_contents($pipes[2]);
    fclose($pipes[1]); fclose($pipes[2]);
    $exit = proc_close($proc);

    return ['ok' => $exit === 0, 'exit' => $exit, 'output' => $out];
}

