# tcp_framework.py
import asyncio, json, itertools, time, logging

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
log = logging.getLogger("tcp")

# ──────────────────────────── 帧协议 ────────────────────────────
# 4 字节大端长度 + JSON 载荷；二进制扩展只需把 payload 换成 bytes 分帧发送
async def send_frame(writer, msg: dict):
    data = json.dumps(msg, ensure_ascii=False).encode()
    writer.write(len(data).to_bytes(4, "big") + data)
    await writer.drain()

async def recv_frame(reader) -> dict | None:
    hdr = await reader.readexactly(4)
    n = int.from_bytes(hdr, "big")
    if n == 0 or n > 16 * 1024 * 1024:
        raise ConnectionError(f"bad frame size {n}")
    return json.loads(await reader.readexactly(n))

# ──────────────────────────── 服务端 ────────────────────────────
class ConnectionManager:
    """按 conn_id 管理多条连接；同 id 重连时踢掉旧的"""

    def __init__(self):
        self._conns: dict[str, asyncio.StreamWriter] = {}
        self._meta: dict[str, dict] = {}
        self._seq = itertools.count(1)

    def register(self, writer) -> str:
        cid = f"c{next(self._seq)}"
        self._conns[cid] = writer
        self._meta[cid] = {"peer": writer.get_extra_info("peername"), "ts": time.time()}
        return cid

    def bind(self, cid: str, writer):
        old = self._conns.get(cid)
        if old and old is not writer:
            old.close()                      # 踢掉同 id 的旧连接
        self._conns[cid] = writer
        self._meta[cid] = {"peer": writer.get_extra_info("peername"), "ts": time.time()}

    def get(self, cid):    return self._conns.get(cid)
    def ids(self):         return list(self._conns)
    def drop(self, cid):   self._conns.pop(cid, None); self._meta.pop(cid, None)

    async def send(self, cid, msg) -> bool:
        w = self._conns.get(cid)
        if not w or w.is_closing():
            return False
        try:
            await send_frame(w, msg)
            return True
        except (ConnectionError, OSError):
            self.drop(cid)
            return False

    async def broadcast(self, msg) -> int:
        ok = 0
        for cid in self.ids():
            if await self.send(cid, msg):
                ok += 1
        return ok


class TCPServer:
    def __init__(self, host="0.0.0.0", port=9000, idle_timeout=60):
        self.host, self.port, self.idle = host, port, idle_timeout
        self.mgr = ConnectionManager()
        self.on_message = self._default_on_message   # (cid, msg) -> awaitable | None

    async def _default_on_message(self, cid, msg):
        if msg.get("type") == "ping":
            await self.mgr.send(cid, {"type": "pong", "ts": time.time()})
        else:
            log.info("recv cid=%s %s", cid, msg)

    async def _handle(self, reader, writer):
        cid = None
        try:
            hello = await asyncio.wait_for(recv_frame(reader), timeout=10)
            cid = hello.get("conn_id")
            if cid:
                self.mgr.bind(cid, writer)      # 携带旧 id → 断线重连续上
            else:
                cid = self.mgr.register(writer)
            await send_frame(writer, {"type": "welcome", "conn_id": cid})
            log.info("online %s from %s", cid, writer.get_extra_info("peername"))

            while True:
                msg = await asyncio.wait_for(recv_frame(reader), timeout=self.idle)
                res = self.on_message(cid, msg)
                if asyncio.iscoroutine(res):
