用法: python3 local_enum.py [--output report.json] [--timeout 5]
仅读取本机状态, 不写不改。
"""
import argparse
import glob
import json
import os
import pwd
import grp
import re
import shutil
import socket
import subprocess
import sys
import time

TIMEOUT = 5


def run(cmd: list[str]) -> str:
    """执行命令, 失败返回空串, 永不抛异常。"""
    try:
        p = subprocess.run(cmd, capture_output=True, text=True, timeout=TIMEOUT)
        return (p.stdout or p.stderr).strip()
    except Exception:
        return ""


# ---------- 1. 本机服务 ----------
def enum_services() -> dict:
    out = {"systemd": [], "init_d": [], "listening": [], "docker": []}
    if shutil.which("systemctl"):
        for line in run(["systemctl", "list-units", "--type=service",
                         "--state=running", "--no-pager", "--no-legend"]).splitlines():
            parts = line.split()
            if parts:
                out["systemd"].append({"unit": parts[0],
                                       "load": parts[1] if len(parts) > 1 else "",
                                       "active": parts[2] if len(parts) > 2 else "",
                                       "description": " ".join(parts[4:]) if len(parts) > 4 else ""})
    for path in sorted(glob.glob("/etc/init.d/*")):
        out["init_d"].append(os.path.basename(path))
    # 监听端口: 优先 ss, 回退 netstat
    ss_out = run(["ss", "-lntup"]) if shutil.which("ss") else run(["netstat", "-lntup"])
    for line in ss_out.splitlines()[1:]:
        m = re.match(r'(\S+)\s+(\S+)\s+(\S+)\s+(\S+)(?:\s+)(.*)', line)
        if m:
            proto, local, _peer, state, proc = m.groups()
            out["listening"].append({"proto": proto, "local": local,
                                     "state": state, "process": proc.strip()})
    if shutil.which("docker"):
        out["docker"] = [l for l in run(["docker", "ps", "--format", "{{.Names}}\t{{.Image}}\t{{.Ports}}"]).splitlines() if l]
    return out


# ---------- 2. 计划任务 ----------
