## `lcs/frame.py` — 帧格式

```python
from __future__ import annotations

import asyncio
import json
import struct
import time
from typing import Any, Optional

MAX_FRAME = 8 << 20            # 单帧上限 8MB
_LEN = struct.Struct(">I")      # 4 字节大端长度前缀


class ProtocolError(Exception):
    pass


class Frame:
    __slots__ = ("type", "data", "seq", "ts")

    def __init__(self, type: str, data: Any = None, seq: int = 0, ts: Optional[float] = None):
        self.type = type
        self.data = {} if data is None else data
        self.seq = seq
        self.ts = time.time() if ts is None else ts

    def encode(self) -> bytes:
        body = json.dumps(
            {"t": self.type, "s": self.seq, "ts": self.ts, "d": self.data},
            ensure_ascii=False, separators=(",", ":"),
        ).encode("utf-8")
        if len(body) > MAX_FRAME:
            raise ProtocolError(f"frame too large: {len(body)}")
        return _LEN.pack(len(body)) + body

    @classmethod
    def decode(cls, body: bytes) -> "Frame":
        obj = json.loads(body)
        if not isinstance(obj, dict) or "t" not in obj:
            raise ProtocolError("bad frame")
        return cls(obj["t"], obj.get("d"), obj.get("s", 0), obj.get("ts"))

    def __repr__(self) -> str:
        return f"<Frame {self.type} seq={self.seq} {self.data!r}>"


async def read_frame(reader: asyncio.StreamReader) -> Optional[Frame]:
    """返回 None 表示对端已正常关闭（EOF）。"""
    try:
        head = await reader.readexactly(4)
    except (asyncio.IncompleteReadError, ConnectionResetError):
        return None
    (size,) = _LEN.unpack(head)
    if size == 0 or size > MAX_FRAME:
        raise ProtocolError(f"illegal frame size: {size}")
    body = await reader.readexactly(size)   # IncompleteReadError 向上抛，视为异常断线
    return Frame.decode(body)
```

## `lcs/connection.py` — 单条连接与连接表

```python
from __future__ import annotations

import asyncio
import time
from typing import Any, Callable, Dict, Iterator, List, Optional

from .frame import Frame, ProtocolError, read_frame


class Connection:
    """服务端侧的一条已握手连接。写入串行化，last_seen 由读循环更新。"""

    def __init__(self, cid: str, reader: asyncio.StreamReader, writer: asyncio.StreamWriter,
                 meta: Optional[Dict[str, Any]] = None):
        self.id = cid
        self.meta = meta or {}
        self.reader = reader
        self.writer = writer
        self.alive = True
        self.connected_at = time.monotonic()
        self.last_seen = self.connected_at
        self.bytes_in = 0
        self.bytes_out = 0
        peer = writer.get_extra_info("peername")
        self.peer = f"{peer[0]}:{peer[1]}" if isinstance(peer, tuple) and len(peer) >= 2 else str(peer)
        self._wlock = asyncio.Lock()

    async def send(self, type: str, data: Any = None) -> bool:
        """返回 False 表示这条连接已死（不抛异常）。"""
        if not self.alive:
            return False
        raw = Frame(type, data).encode()
        try:
            async with self._wlock:
                self.writer.write(raw)
                await self.writer.drain()
            self.bytes_out += len(raw)
            return True
        except (ConnectionError, RuntimeError, OSError):
            self.alive = False
            return False

    def close(self) -> None:
        self.alive = False
        try:
            self.writer.close()
        except Exception:
            pass

    def idle(self) -> float:
        return time.monotonic() - self.last_seen


class ConnectionManager:
    def __init__(self) -> None:
        self._by_id: Dict[str, Connection] = {}

    def add(self, conn: Connection) -> None:
        self._by_id[conn.id] = conn

    def remove(self, cid: str) -> Optional[Connection]:
        return self._by_id.pop(cid, None)

    def get(self, cid: str) -> Optional[Connection]:
        return self._by_id.get(cid)

    def ids(self) -> List[str]:
