import json
import os
import shutil
import subprocess

def run_command(cmd):
    """Executes a command and returns the stdout lines, or an empty list on failure."""
    try:
        result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True, check=False)
        return [line.strip() for line in result.stdout.splitlines() if line.strip()]
    except Exception:
        return []

def get_current_user_info():
    info = {
        "uid": os.getuid() if hasattr(os, "getuid") else None,
        "gid": os.getgid() if hasattr(os, "getgid") else None,
        "username": os.environ.get("USER") or os.environ.get("USERNAME"),
        "groups": run_command(["id"])
    }
    # Check sudo privileges if available (non-interactive)
    sudo_check = run_command(["sudo", "-n", "-l"])
    info["sudo_l"] = sudo_check if sudo_check else "No passwordless sudo or sudo unavailable"
    return info

def get_services():
    services = []
    if shutil.which("systemctl"):
        raw = run_command(["systemctl", "list-units", "--type=service", "--state=running", "--no-pager", "--no-legend"])
        for line in raw:
            parts = line.split(maxsplit=4)
            if parts:
                services.append(parts[0])
    elif shutil.which("service"):
        services = run_command(["service", "--status-all"])
    return services

def get_scheduled_tasks():
    tasks = {
        "crontab": run_command(["crontab", "-l"]),
        "cron_dirs": []
    }
    cron_paths = ["/etc/crontab", "/etc/cron.d", "/etc/cron.daily", "/etc/cron.hourly"]
    for path in cron_paths:
        if os.path.exists(path):
            if os.path.isdir(path):
                try:
                    tasks["cron_dirs"].extend([os.path.join(path, f) for f in os.listdir(path)])
                except PermissionError:
                    pass
            else:
                tasks["cron_dirs"].append(path)

    if shutil.which("systemctl"):
        tasks["systemd_timers"] = run_command(["systemctl", "list-timers", "--no-pager", "--no-legend"])

    return tasks

def get_writable_directories(search_paths=None):
    if search_paths is None:
        search_paths = ["/tmp", "/var/tmp", "/dev/shm", "/etc", "/opt"]
    writable = []
    for path in search_paths:
        if os.path.isdir(path):
            for root, dirs, _ in os.walk(path):
                if os.access(root, os.W_OK):
                    writable.append(root)
    return list(set(writable))

def get_suid_files():
    # Uses the 'find' utility to identify files with SUID permission bit set
    if shutil.which("find"):
        return run_command(["find", "/", "-perm", "-4000", "-type", "f"])
    return []

def main():
    audit_data = {
        "user_privileges": get_current_user_info(),
        "services": get_services(),
        "scheduled_tasks": get_scheduled_tasks(),
        "writable_directories": get_writable_directories(),
        "suid_files": get_suid_files()
    }

    print(json.dumps(audit_data, indent=2))

if __name__ == "__main__":
    main()
